openapi_config.spec:
{
  "openapi": "3.1.0",
  "info": {
    "title": "OpenConnector management",
    "version": "0.1.0",
    "description": "Manage connections, OAuth clients, runtime access, policies, subscriptions, files and execution history through the native API. Provider actions use OpenConnector's five discovery tools. Writes take effect immediately."
  },
  "tags": [
    {
      "name": "System",
      "description": "Runtime health and server-level status."
    },
    {
      "name": "Catalog",
      "description": "Provider and action metadata used by users and agents."
    },
    {
      "name": "Connections",
      "description": "Local provider credentials and connection state."
    },
    {
      "name": "OAuth",
      "description": "Local OAuth client configuration and authorization flow."
    },
    {
      "name": "Access",
      "description": "Runtime execution policy and bearer tokens for /v1 and MCP clients."
    },
    {
      "name": "Files",
      "description": "Local temporary file transit for provider actions."
    },
    {
      "name": "Runs",
      "description": "Local action execution and recent run history."
    },
    {
      "name": "Triggers",
      "description": "Registered provider Trigger operations and owned remote subscription cleanup."
    },
    {
      "name": "Proxy",
      "description": "Provider API proxy requests using the selected local or SaaS connection."
    },
    {
      "name": "MCP",
      "description": "Stateless MCP POST endpoint and tool metadata."
    }
  ],
  "paths": {
    "/api/providers": {
      "get": {
        "tags": [
          "Catalog"
        ],
        "summary": "List provider catalog entries.",
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/ProviderDefinition"
                  }
                }
              }
            }
          },
          "404": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ErrorResponse"
                }
              }
            }
          }
        }
      }
    },
    "/api/providers/{service}": {
      "get": {
        "tags": [
          "Catalog"
        ],
        "summary": "Get one provider catalog entry.",
        "parameters": [
          {
            "name": "service",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ProviderDefinition"
                }
              }
            }
          },
          "404": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ErrorResponse"
                }
              }
            }
          }
        }
      }
    },
    "/api/actions": {
      "get": {
        "tags": [
          "Catalog"
        ],
        "summary": "List all catalog actions.",
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/ActionDefinition"
                  }
                }
              }
            }
          },
          "404": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ErrorResponse"
                }
              }
            }
          }
        }
      }
    },
    "/api/actions/search": {
      "get": {
        "tags": [
          "Catalog"
        ],
        "summary": "Fuzzy keyword search over the action catalog.",
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/ActionSearchResult"
                  }
                }
              }
            }
          },
          "404": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ErrorResponse"
                }
              }
            }
          }
        }
      }
    },
    "/v1/providers/{service}/setup": {
      "get": {
        "tags": [
          "Connections"
        ],
        "summary": "Describe the inputs a provider needs before it can be connected.",
        "description": "Requires administrator authentication. Lists credential fields, OAuth client inputs, scopes, registration help, the callback URL to register and the OAuth client inputs still missing. Never includes saved values.",
        "parameters": [
          {
            "name": "service",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": true,
                      "type": "boolean"
                    },
                    "message": {
                      "const": "OK",
                      "type": "string"
                    },
                    "data": {
                      "type": "object",
                      "properties": {
                        "service": {
                          "type": "string"
                        },
                        "auth": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "type": {
                                "type": "string",
                                "enum": [
                                  "no_auth",
                                  "api_key",
                                  "custom_credential",
                                  "oauth2"
                                ],
                                "description": "Credential type."
                              },
                              "label": {
                                "type": "string",
                                "description": "Provider-declared display name for this auth mode, e.g. Service Account."
                              },
                              "description": {
                                "type": "string",
                                "description": "Provider-declared help text describing when to use this auth mode."
                              },
                              "fields": {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "key": {
                                      "type": "string"
                                    },
                                    "label": {
                                      "type": "string"
                                    },
                                    "inputType": {
                                      "type": "string",
                                      "enum": [
                                        "text",
                                        "password",
                                        "textarea",
                                        "json"
                                      ],
                                      "description": "Suggested form control."
                                    },
                                    "required": {
                                      "type": "boolean"
                                    },
                                    "secret": {
                                      "type": "boolean",
                                      "description": "Whether the value is stored as a secret and never returned."
                                    },
                                    "placeholder": {
                                      "type": "string",
                                      "description": "Input placeholder."
                                    },
                                    "description": {
                                      "type": "string",
                                      "description": "Where the user obtains this value."
                                    },
                                    "location": {
                                      "type": "string",
                                      "enum": [
                                        "extra",
                                        "secretExtra"
                                      ],
                                      "description": "Request object an OAuth client field is submitted in; absent for clientId and clientSecret."
                                    },
                                    "defaultValue": {
                                      "type": "string",
                                      "description": "Value applied when an OAuth client field is omitted."
                                    }
                                  },
                                  "additionalProperties": false,
                                  "required": [
                                    "key",
                                    "label",
                                    "inputType",
                                    "required",
                                    "secret"
                                  ],
                                  "description": "One input a connection or OAuth client form asks for."
                                }
                              },
                              "clientFields": {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "key": {
                                      "type": "string"
                                    },
                                    "label": {
                                      "type": "string"
                                    },
                                    "inputType": {
                                      "type": "string",
                                      "enum": [
                                        "text",
                                        "password",
                                        "textarea",
                                        "json"
                                      ],
                                      "description": "Suggested form control."
                                    },
                                    "required": {
                                      "type": "boolean"
                                    },
                                    "secret": {
                                      "type": "boolean",
                                      "description": "Whether the value is stored as a secret and never returned."
                                    },
                                    "placeholder": {
                                      "type": "string",
                                      "description": "Input placeholder."
                                    },
                                    "description": {
                                      "type": "string",
                                      "description": "Where the user obtains this value."
                                    },
                                    "location": {
                                      "type": "string",
                                      "enum": [
                                        "extra",
                                        "secretExtra"
                                      ],
                                      "description": "Request object an OAuth client field is submitted in; absent for clientId and clientSecret."
                                    },
                                    "defaultValue": {
                                      "type": "string",
                                      "description": "Value applied when an OAuth client field is omitted."
                                    }
                                  },
                                  "additionalProperties": false,
                                  "required": [
                                    "key",
                                    "label",
                                    "inputType",
                                    "required",
                                    "secret"
                                  ],
                                  "description": "One input a connection or OAuth client form asks for."
                                }
                              },
                              "clientSetup": {
                                "type": "object",
                                "properties": {
                                  "docsUrl": {
                                    "type": "string",
                                    "description": "Provider page where the OAuth app is registered."
                                  },
                                  "steps": {
                                    "type": "array",
                                    "items": {
                                      "type": "string",
                                      "minLength": 1
                                    },
                                    "description": "Ordered setup steps."
                                  }
                                },
                                "additionalProperties": false,
                                "required": [
                                  "steps"
                                ],
                                "description": "How to register the provider OAuth app."
                              },
                              "scopes": {
                                "type": "array",
                                "items": {
                                  "type": "string",
                                  "minLength": 1
                                },
                                "description": "Default provider scopes when no explicit selection is made."
                              },
                              "optionalScopes": {
                                "type": "array",
                                "items": {
                                  "type": "string",
                                  "minLength": 1
                                },
                                "description": "Additional provider scopes for explicit selection. requestedScopes replaces the default scope list."
                              },
                              "authorizationOptions": {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "id": {
                                      "type": "string"
                                    },
                                    "label": {
                                      "type": "string"
                                    },
                                    "description": {
                                      "type": "string"
                                    },
                                    "required": {
                                      "type": "boolean"
                                    },
                                    "defaultSelected": {
                                      "type": "boolean"
                                    },
                                    "risk": {
                                      "type": "string",
                                      "enum": [
                                        "standard",
                                        "sensitive",
                                        "destructive"
                                      ],
                                      "description": "How much access the option grants."
                                    },
                                    "requires": {
                                      "type": "array",
                                      "items": {
                                        "type": "string",
                                        "minLength": 1
                                      },
                                      "description": "Option ids that must be selected together with this one."
                                    }
                                  },
                                  "additionalProperties": false,
                                  "required": [
                                    "id",
                                    "label",
                                    "description",
                                    "required",
                                    "defaultSelected",
                                    "risk"
                                  ],
                                  "description": "One selectable authorization option."
                                }
                              }
                            },
                            "additionalProperties": false,
                            "required": [
                              "type"
                            ],
                            "description": "One supported credential type with its form metadata."
                          }
                        },
                        "oauthClient": {
                          "type": "object",
                          "properties": {
                            "configured": {
                              "type": "boolean"
                            },
                            "customClientAvailable": {
                              "type": "boolean",
                              "description": "Whether connections may carry their own OAuth client; false for a SaaS default source."
                            },
                            "expectedRedirectUri": {
                              "type": "string",
                              "description": "Callback URL: the SaaS provider config callback for a SaaS source; otherwise the local override or runtime callback."
                            },
                            "missingFields": {
                              "type": "array",
                              "items": {
                                "type": "string",
                                "minLength": 1
                              },
                              "description": "Required local client inputs absent from storage; empty for a SaaS source."
                            }
                          },
                          "additionalProperties": false,
                          "description": "Default OAuth source configuration; present when the provider supports OAuth."
                        }
                      },
                      "additionalProperties": false,
                      "required": [
                        "service",
                        "auth"
                      ],
                      "description": "Setup requirements and OAuth client state for one provider, without saved values."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "meta"
                  ],
                  "description": "Runtime success envelope."
                }
              }
            }
          },
          "401": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": false,
                      "type": "boolean"
                    },
                    "message": {
                      "type": "string",
                      "description": "Human-readable error message."
                    },
                    "data": {
                      "description": "Provider or validation error details."
                    },
                    "errorCode": {
                      "type": "string",
                      "description": "Stable machine-readable error code."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "errorCode",
                    "meta"
                  ],
                  "description": "Runtime failure envelope."
                }
              }
            }
          },
          "403": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": false,
                      "type": "boolean"
                    },
                    "message": {
                      "type": "string",
                      "description": "Human-readable error message."
                    },
                    "data": {
                      "description": "Provider or validation error details."
                    },
                    "errorCode": {
                      "type": "string",
                      "description": "Stable machine-readable error code."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "errorCode",
                    "meta"
                  ],
                  "description": "Runtime failure envelope."
                }
              }
            }
          },
          "404": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": false,
                      "type": "boolean"
                    },
                    "message": {
                      "type": "string",
                      "description": "Human-readable error message."
                    },
                    "data": {
                      "description": "Provider or validation error details."
                    },
                    "errorCode": {
                      "type": "string",
                      "description": "Stable machine-readable error code."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "errorCode",
                    "meta"
                  ],
                  "description": "Runtime failure envelope."
                }
              }
            }
          }
        }
      }
    },
    "/v1/connections": {
      "get": {
        "tags": [
          "Connections"
        ],
        "summary": "List manageable connections.",
        "parameters": [
          {
            "name": "status",
            "in": "query",
            "required": false,
            "schema": {
              "type": "string",
              "enum": [
                "active",
                "reauth_required",
                "error",
                "disconnected"
              ],
              "description": "Connection state."
            },
            "description": "Filter by current connection state."
          }
        ],
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": true,
                      "type": "boolean"
                    },
                    "message": {
                      "const": "OK",
                      "type": "string"
                    },
                    "data": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "id": {
                            "type": "string",
                            "description": "Stable local connection identifier."
                          },
                          "providerAccountId": {
                            "type": "string",
                            "description": "The provider account identifier."
                          },
                          "service": {
                            "type": "string",
                            "description": "Provider service identifier."
                          },
                          "status": {
                            "type": "string",
                            "enum": [
                              "active",
                              "reauth_required",
                              "error",
                              "disconnected"
                            ],
                            "description": "Current connection state."
                          },
                          "alias": {
                            "type": "string",
                            "description": "Named connection. Same fact as MCP connectionName; HTTP alias, connectionName, and x-oo-connector-alias are equivalent. Defaults to default."
                          },
                          "authType": {
                            "type": "string",
                            "description": "Connection authentication type."
                          },
                          "displayName": {
                            "type": "string",
                            "description": "Human-readable account label."
                          },
                          "accountLabel": {
                            "type": "string",
                            "description": "Same value as displayName. Kept for existing /v1 clients."
                          },
                          "isDefault": {
                            "type": "boolean",
                            "description": "Whether this is the default connection. Same fact as MCP default."
                          },
                          "scopes": {
                            "type": "array",
                            "items": {
                              "type": "string"
                            },
                            "description": "Granted scopes. Same fact as MCP profile.grantedScopes."
                          },
                          "marketplace": {
                            "type": "object",
                            "properties": {
                              "id": {
                                "type": "string",
                                "description": "Marketplace identifier."
                              },
                              "pricing": {
                                "type": "string",
                                "enum": [
                                  "free",
                                  "metered"
                                ]
                              }
                            },
                            "additionalProperties": false,
                            "required": [
                              "id",
                              "pricing"
                            ],
                            "description": "Marketplace source for a virtual connection."
                          },
                          "comment": {
                            "anyOf": [
                              {
                                "type": "string",
                                "description": "An optional administrator note."
                              },
                              {
                                "type": "null"
                              }
                            ],
                            "description": "An optional administrator note."
                          }
                        },
                        "additionalProperties": false,
                        "description": "A stored connection visible to the administrator."
                      }
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "meta"
                  ],
                  "description": "Runtime success envelope."
                }
              }
            }
          },
          "401": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": false,
                      "type": "boolean"
                    },
                    "message": {
                      "type": "string",
                      "description": "Human-readable error message."
                    },
                    "data": {
                      "description": "Provider or validation error details."
                    },
                    "errorCode": {
                      "type": "string",
                      "description": "Stable machine-readable error code."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "errorCode",
                    "meta"
                  ],
                  "description": "Runtime failure envelope."
                }
              }
            }
          },
          "403": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": false,
                      "type": "boolean"
                    },
                    "message": {
                      "type": "string",
                      "description": "Human-readable error message."
                    },
                    "data": {
                      "description": "Provider or validation error details."
                    },
                    "errorCode": {
                      "type": "string",
                      "description": "Stable machine-readable error code."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "errorCode",
                    "meta"
                  ],
                  "description": "Runtime failure envelope."
                }
              }
            }
          }
        }
      }
    },
    "/v1/connections/by-id/{appId}": {
      "get": {
        "tags": [
          "Connections"
        ],
        "summary": "Get the current connection state.",
        "parameters": [
          {
            "name": "appId",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "success": {
                      "const": true,
                      "type": "boolean"
                    },
                    "message": {
                      "const": "OK",
                      "type": "string"
                    },
                    "data": {
                      "type": "object",
                      "properties": {
                        "id": {
                          "type": "string",
                          "description": "Stable local connection identifier."
                        },
                        "providerAccountId": {
                          "type": "string",
                          "description": "The provider account identifier."
                        },
                        "service": {
                          "type": "string",
                          "description": "Provider service identifier."
                        },
                        "status": {
                          "type": "string",
                          "enum": [
                            "active",
                            "reauth_required",
                            "error",
                            "disconnected"
                          ],
                          "description": "Current connection state."
                        },
                        "alias": {
                          "type": "string",
                          "description": "Named connection. Same fact as MCP connectionName; HTTP alias, connectionName, and x-oo-connector-alias are equivalent. Defaults to default."
                        },
                        "authType": {
                          "type": "string",
                          "description": "Connection authentication type."
                        },
                        "displayName": {
                          "type": "string",
                          "description": "Human-readable account label."
                        },
                        "accountLabel": {
                          "type": "string",
                          "description": "Same value as displayName. Kept for existing /v1 clients."
                        },
                        "isDefault": {
                          "type": "boolean",
                          "description": "Whether this is the default connection. Same fact as MCP default."
                        },
                        "scopes": {
                          "type": "array",
                          "items": {
                            "type": "string"
                          },
                          "description": "Granted scopes. Same fact as MCP profile.grantedScopes."
                        },
                        "marketplace": {
                          "type": "object",
                          "properties": {
                            "id": {
                              "type": "string",
                              "description": "Marketplace identifier."
                            },
                            "pricing": {
                              "type": "string",
                              "enum": [
                                "free",
                                "metered"
                              ]
                            }
                          },
                          "additionalProperties": false,
                          "required": [
                            "id",
                            "pricing"
                          ],
                          "description": "Marketplace source for a virtual connection."
                        },
                        "comment": {
                          "anyOf": [
                            {
                              "type": "string",
                              "description": "An optional administrator note."
                            },
                            {
                              "type": "null"
                            }
                          ],
                          "description": "An optional administrator note."
                        }
                      },
                      "additionalProperties": false,
                      "description": "A stored connection visible to the administrator."
                    },
                    "meta": {
                      "type": "object",
                      "additionalProperties": true
                    }
                  },
                  "additionalProperties": false,
                  "required": [
                    "success",
                    "message",
                    "data",
                    "meta"
                  ],
                  "description": "Runtime success envelope."
                }
              }
            }
          },
          "401": {
            "description": "JSON response.",
