      "delete": {
        "tags": [
          "Connections"
        ],
        "summary": "Disconnect a provider.",
        "requestBody": {
          "required": false,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "connectionName": {
                    "type": "string",
                    "description": "Named connection. Defaults to default."
                  },
                  "revoke": {
                    "type": "boolean",
                    "default": false,
                    "description": "Also request OAuth token revocation after deleting the local credential. Related connections may lose authorization depending on the provider's revocation policy."
                  }
                },
                "additionalProperties": false
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "anyOf": [
                    {
                      "$ref": "#/components/schemas/ConnectionSummary"
                    },
                    {
                      "type": "object",
                      "properties": {
                        "service": {
                          "type": "string"
                        },
                        "configured": {
                          "const": false,
                          "type": "boolean"
                        },
                        "revoked": {
                          "type": "string",
                          "enum": [
                            "done",
                            "failed",
                            "unsupported",
                            "skipped"
                          ],
                          "description": "What the disconnect did about the grant at the provider: done (its revocation endpoint accepted the token), failed (it refused or could not be reached; the credential is deleted here regardless), unsupported (no revocation endpoint declared, no OAuth token held, or a SaaS connection) or skipped (the request body did not set revoke: true, the default)."
                        }
                      },
                      "additionalProperties": false,
                      "required": [
                        "service",
                        "configured",
                        "revoked"
                      ],
                      "description": "Disconnected provider summary."
                    }
                  ]
                }
              }
            }
          },
          "404": {
            "description": "JSON response.",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/ErrorResponse"
                }
              }
            }
          }
        }
      }
    },
