          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "service": {
                    "type": "string",
                    "description": "Provider service identifier."
                  },
                  "connectionName": {
                    "type": "string",
                    "description": "Optional local connection name. Defaults to default."
                  },
                  "clientId": {
                    "type": "string",
                    "description": "Optional connection-scoped OAuth app client id."
                  },
                  "clientSecret": {
                    "type": "string",
                    "description": "Optional connection-scoped OAuth app client secret."
                  },
                  "requestedScopes": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    },
                    "description": "Optional complete non-empty scope list replacing the provider defaults. Each scope must be declared in scopes or optionalScopes; default scopes are not added automatically.",
                    "minItems": 1
                  },
                  "redirectUri": {
                    "type": "string",
                    "description": "Optional redirect URI registered with the connection-scoped OAuth app instead of the runtime callback. Same rules as OAuthClientConfigRequest.redirectUri."
                  },
                  "authorizationOptionIds": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    },
                    "description": "Optional provider authorization option ids selected for this connection."
                  },
                  "extra": {
                    "type": "object",
                    "additionalProperties": {
                      "type": "string"
                    },
                    "description": "Provider-declared non-secret OAuth client fields."
                  },
                  "secretExtra": {
                    "type": "object",
                    "additionalProperties": {
                      "type": "string"
                    },
                    "description": "Provider-declared secret OAuth client fields."
